import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between start and end nodes using Dijkstra's algorithm.

    Args:
        edges: List of (from_node, to_node, weight) tuples
        start: Starting node
        end: Ending node

    Returns:
        (distance, path) tuple where distance is total weight and path is list of nodes.
        If no path exists: (None, None).
        ValueError raised if any edge weight is negative.
    """
    # Case when start equals end
    if start == end:
        return (0, [start])

    # Check for negative weights and collect all nodes in the graph
    nodes = set()
    has_negative = False
    for from_node, to_node, weight in edges:
        nodes.add(from_node)
        nodes.add(to_node)
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")

    # Ensure start and end are tracked
    nodes.add(start)
    nodes.add(end)

    # Build adjacency list (including start/end even with no outgoing edges)
    graph = {node: [] for node in nodes}
    for from_node, to_node, weight in edges:
        if from_node in graph and to_node in graph:  # safety check
            graph[from_node].append((to_node, weight))

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in nodes}
    previous = {node: None for node in nodes}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # Skip if we've already found a shorter path to this node
        if current_distance > distances[current_node]:
            continue

        # Explore neighbors (if current node has outgoing edges)
        if current_node in graph:
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current_node
                    heapq.heappush(heap, (distance, neighbor))

    # If destination is unreachable
    if distances.get(end, float('inf')) == float('inf'):
        return (None, None)

    # Reconstruct the path from end to start
    path = []
    current = end
    while current in previous:
        path.append(current)
        current = previous[current]

    # If we somehow can't trace back to start, treat as no path
    if not path or path[0] != start:
        return (None, None)

    path.reverse()
    return (distances[end], path)
